import math
import random

# Comportements de 15 apprenants : (heures de cours, exercises réussis)
POINTS = [
    (1.0, 2.0), (1.2, 1.8), (0.8, 2.4), (1.5, 2.1), (1.1, 2.2),
    (5.0, 5.5), (5.4, 5.1), (4.8, 5.9), (5.2, 5.4), (5.3, 5.2),
    (8.0, 1.0), (8.4, 1.4), (7.8, 0.6), (8.2, 1.1), (7.9, 0.9),
]


def distance(a, b):
    """Distance euclidienne entre deux points de même dimension."""
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))


def k_moyennes(points, k=3, iterations=20, graine=1):
    """Retourne (affectations, centres) après convergence ou saturation."""
    rng = random.Random(graine)
    centres = [tuple(p) for p in rng.sample(list(points), k)]
    affectations = [None] * len(points)

    for _ in range(iterations):
        nouvelles = [
            min(range(k), key=lambda i: distance(points[j], centres[i]))
            for j in range(len(points))
        ]
        if nouvelles == affectations:
            affectations = nouvelles
            break
        affectations = nouvelles

        for i in range(k):
            groupe = [points[j] for j in range(len(points)) if affectations[j] == i]
            if groupe:
                centres[i] = tuple(sum(c) / len(groupe) for c in zip(*groupe))

    return affectations, centres


def inertie(points, centres, affectations):
    """Somme des carrés des distances point -> centre de son groupe."""
    total = 0.0
    for j, point in enumerate(points):
        total += distance(point, centres[affectations[j]]) ** 2
    return total


if __name__ == "__main__":
    affectations, centres = k_moyennes(POINTS, k=3)

    for i in range(len(centres)):
        effectif = affectations.count(i)
        cx, cy = centres[i]
        print("cluster", i, "->", effectif, "points, centre =", (round(cx, 2), round(cy, 2)))

    print("inertie =", round(inertie(POINTS, centres, affectations), 3))

    # Vérification visuelle : les regroupements suivent-ils les trois nuages ?
    for j, point in enumerate(POINTS):
        print(point, "=> cluster", affectations[j])
